<script setup lang="ts">
import { ImagePlus, X, Save, Tag, Search } from '@lucide/vue';
const config = useRuntimeConfig();
const { token } = useWorkspaceSession();
const productEditor = useState<any | null>('admin-product-editor', () => null);
const categories = ref<any[]>([]); const tab = ref<'main' | 'images' | 'seo'>('main'); const saving = ref(false); const categorySearch = ref(''); const message = ref('');
const visibleCategories = computed(() => categories.value.filter(category => !categorySearch.value || category.nameRu.toLowerCase().includes(categorySearch.value.toLowerCase())));
async function loadCategories() { if (!token.value || categories.value.length) return; categories.value = await $fetch<any[]>('/admin/categories', { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${token.value}` } }); }
watch(productEditor, (value) => { if (value) { tab.value = 'main'; loadCategories(); } });
function addImage() { productEditor.value?.images.push({ url: '', alt: '' }); }
function removeImage(index: number) { productEditor.value?.images.splice(index, 1); }
async function save() { if (!productEditor.value) return; saving.value = true; message.value = ''; try { await $fetch(`/admin/products/${productEditor.value.id}`, { baseURL: config.public.apiBase, method: 'PATCH', headers: { Authorization: `Bearer ${token.value}` }, body: { nameRu: productEditor.value.nameRu, descriptionRu: productEditor.value.descriptionRu, price: Number(productEditor.value.price), stock: Number(productEditor.value.stock), isActive: productEditor.value.isActive, images: productEditor.value.images.filter((image: any) => image.url), categoryIds: productEditor.value.categoryIds, metaTitle: productEditor.value.metaTitle, metaDesc: productEditor.value.metaDesc, canonical: productEditor.value.canonical } }); message.value = 'Сохранено'; setTimeout(() => { productEditor.value = null; }, 700); } catch (e: any) { message.value = e?.data?.message || 'Не удалось сохранить'; } finally { saving.value = false; } }
</script>
<template>
  <aside v-if="productEditor" class="editor-backdrop" @click.self="productEditor = null">
    <section class="editor-drawer">
      <header class="editor-header"><div><p class="eyebrow">КАТАЛОГ / РЕДАКТИРОВАНИЕ</p><h2>Карточка товара</h2><span>{{ productEditor.nameRu }}</span></div><button class="close" @click="productEditor = null"><X :size="19" /></button></header>
      <nav class="editor-tabs"><button :class="{active: tab === 'main'}" @click="tab='main'">Основное</button><button :class="{active: tab === 'images'}" @click="tab='images'"><ImagePlus :size="15" /> Изображения <b>{{ productEditor.images.length }}</b></button><button :class="{active: tab === 'seo'}" @click="tab='seo'">SEO</button></nav>
      <div class="editor-scroll">
        <div v-if="tab === 'main'" class="editor-fields"><label>Название товара<input v-model="productEditor.nameRu" /></label><label>Описание<textarea v-model="productEditor.descriptionRu" rows="6"></textarea></label><div class="two-fields"><label>Цена, ₽<input v-model.number="productEditor.price" type="number" min="0" /></label><label>Остаток<input v-model.number="productEditor.stock" type="number" min="0" /></label></div><div class="category-box"><div class="field-title"><Tag :size="15" /> Категории</div><label class="category-search"><Search :size="14" /><input v-model="categorySearch" placeholder="Найти категорию" /></label><div class="category-list"><label v-for="category in visibleCategories" :key="category.id" class="category-option"><input v-model="productEditor.categoryIds" type="checkbox" :value="category.id" />{{ category.nameRu }}</label><p v-if="!visibleCategories.length">Категории не найдены</p></div></div><label class="published"><input v-model="productEditor.isActive" type="checkbox" /> Показывать товар в каталоге</label></div>
        <div v-else-if="tab === 'images'" class="images-editor"><div class="images-intro"><div><h3>Галерея товара</h3><p>Добавьте ссылки на изображения в хорошем качестве.</p></div><button class="outline" @click="addImage"><ImagePlus :size="15" /> Добавить</button></div><div v-for="(image, index) in productEditor.images" :key="index" class="image-card"><div class="image-preview"><img v-if="image.url" :src="image.url" :alt="image.alt" /><ImagePlus v-else :size="24" /></div><div class="image-inputs"><input v-model="image.url" placeholder="https://... URL изображения" /><input v-model="image.alt" placeholder="Alt-текст для SEO" /></div><button class="remove" @click="removeImage(index)"><X :size="16" /></button></div><div v-if="!productEditor.images.length" class="empty-images"><ImagePlus :size="28" /><p>Изображений пока нет</p><button class="outline" @click="addImage">Добавить первое изображение</button></div></div>
        <div v-else class="editor-fields"><div class="seo-note">SEO-поля влияют на сниппет товара в поисковой выдаче.</div><label>Meta Title<input v-model="productEditor.metaTitle" placeholder="Название товара — SARKISIAN" /><small>{{ productEditor.metaTitle.length }}/60 символов</small></label><label>Meta Description<textarea v-model="productEditor.metaDesc" rows="5" placeholder="Краткое описание страницы товара"></textarea><small>{{ productEditor.metaDesc.length }}/160 символов</small></label><label>Canonical URL<input v-model="productEditor.canonical" placeholder="https://sarkisianbrand.ru/catalog/..." /></label></div>
      </div>
      <footer class="editor-footer"><span :class="{success: message === 'Сохранено'}">{{ message }}</span><button class="cancel" @click="productEditor = null">Отмена</button><button class="save" :disabled="saving" @click="save"><Save :size="15" />{{ saving ? 'Сохраняем…' : 'Сохранить товар' }}</button></footer>
    </section>
  </aside>
</template>
<style scoped>
.editor-backdrop{position:fixed;inset:0;background:#10111455;z-index:500}.editor-drawer{position:absolute;right:0;top:0;bottom:0;width:min(560px,94vw);background:#fff;display:flex;flex-direction:column;box-shadow:-12px 0 40px #1112}.editor-header{padding:28px 30px 22px;border-bottom:1px solid #e8e9ec;display:flex;justify-content:space-between}.eyebrow{font-size:10px;letter-spacing:.15em;color:#f15b49;margin:0 0 8px}.editor-header h2{font-size:24px;margin:0 0 6px}.editor-header span{font-size:11px;color:#858991}.close,.remove{border:0;background:none;color:#858991;cursor:pointer}.editor-tabs{display:flex;gap:4px;padding:0 30px;border-bottom:1px solid #e8e9ec}.editor-tabs button{height:46px;border:0;background:none;border-bottom:2px solid transparent;color:#858991;display:flex;align-items:center;gap:6px;font-size:11px}.editor-tabs button.active{color:#1d1e22;border-color:#f15b49}.editor-tabs b{background:#f0f1f3;border-radius:10px;padding:2px 6px;font-size:9px}.editor-scroll{padding:26px 30px;overflow:auto;flex:1}.editor-fields{display:grid;gap:18px}.editor-fields label,.image-inputs{display:grid;gap:7px;color:#74777f;font-size:11px}.editor-fields input,.editor-fields textarea,.image-inputs input{border:1px solid #dfe1e5;padding:0 11px;height:40px;font:12px var(--sb-font);box-sizing:border-box;resize:vertical}.editor-fields textarea{height:auto;padding:11px}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.category-box{border:1px solid #e3e5e8;padding:16px}.field-title{display:flex;align-items:center;gap:7px;font-size:12px;color:#1d1e22;margin-bottom:13px}.category-search{height:34px!important;border:1px solid #e3e5e8;padding:0 9px;display:flex!important;flex-direction:row;align-items:center;gap:6px}.category-search input{border:0!important;height:30px!important;padding:0!important;outline:0;width:100%}.category-list{display:grid;gap:8px;margin-top:13px;max-height:140px;overflow:auto}.category-option{display:flex!important;flex-direction:row;align-items